CREATE TABLE CPF_RUNTIME_INSTANCE_HEALTH (SYSTEM_ID VARCHAR(64) NOT NULL, INSTANCE_ID VARCHAR(128) NOT NULL, VERSION VARCHAR(64), BUILD_SHA VARCHAR(64), STARTED_AT TIMESTAMP(6) NOT NULL, UPTIME_MS BIGINT NOT NULL, LAST_SEEN_AT TIMESTAMP(6) NOT NULL, LIVENESS VARCHAR(32) NOT NULL, READINESS VARCHAR(32) NOT NULL, STARTUP VARCHAR(32) NOT NULL, DRAINING TINYINT NOT NULL DEFAULT 0, MAINTENANCE TINYINT NOT NULL DEFAULT 0, PAYLOAD_JSON LONGTEXT NOT NULL, PRIMARY KEY(SYSTEM_ID,INSTANCE_ID), KEY IX_CPF_RIH_LAST_SEEN(LAST_SEEN_AT), KEY IX_CPF_RIH_READINESS(READINESS,LAST_SEEN_AT));
